"""Level-k coefficient of a product of normalized q-series via the master
formula and its locality refinement."""

from __future__ import annotations

from fractions import Fraction
from itertools import combinations
from typing import Iterator, List, Sequence, Tuple

Tail = Sequence[Fraction]


def coeff(tail: Tail, n: int) -> Fraction:
    """Laurent coefficient [q^n] of f = q^{-1} + a_0 + a_1 q + ...

    The value at n = -1 is the pole coefficient 1, which is also the neutral
    element of multiplication; this is what makes the master formula uniform."""
    if n == -1:
        return Fraction(1)
    if n < -1:
        return Fraction(0)
    return tail[n] if n < len(tail) else Fraction(0)


def weak_compositions(m: int, k: int) -> Iterator[Tuple[int, ...]]:
    """All ways of distributing a budget of k units among m factors."""
    if m == 0:
        if k == 0:
            yield ()
        return
    for first in range(k + 1):
        for rest in weak_compositions(m - 1, k - first):
            yield (first,) + rest


def level_coefficient(tails: Sequence[Tail], k: int) -> Fraction:
    """c_k = [q^{k-m}] prod_i f_i, by the master formula.

    Complexity: binom(m+k-1, k) terms, each a product of at most k nontrivial
    factor coefficients (the early exit on a zero factor helps in practice)."""
    total = Fraction(0)
    for nu in weak_compositions(len(tails), k):
        term = Fraction(1)
        for tail, e in zip(tails, nu):
            term *= coeff(tail, e - 1)
            if term == 0:
                break
        total += term
    return total


def strict_compositions(t: int, k: int, minimum: int = 1) -> Iterator[Tuple[int, ...]]:
    """Compositions of k into exactly t parts, each >= minimum."""
    if t == 0:
        if k == 0:
            yield ()
        return
    for first in range(minimum, k - minimum * (t - 1) + 1):
        for rest in strict_compositions(t - 1, k - first, minimum):
            yield (first,) + rest


def level_coefficient_local(tails: Sequence[Tail], k: int,
                            vanishing_constant_terms: bool = False) -> Fraction:
    """Same value, organized by which factors are excited.

    Only subsets of size <= k contribute (locality); if every factor has
    vanishing constant term, only subsets of size <= k//2 contribute
    (half locality), because an exponent equal to 1 annihilates its term."""
    m = len(tails)
    minimum = 2 if vanishing_constant_terms else 1
    top = k // 2 if vanishing_constant_terms else k
    total = Fraction(1) if k == 0 else Fraction(0)
    for size in range(1, min(top, m) + 1):
        for subset in combinations(range(m), size):
            for nu in strict_compositions(size, k, minimum):
                term = Fraction(1)
                for idx, e in zip(subset, nu):
                    term *= coeff(tails[idx], e - 1)
                    if term == 0:
                        break
                total += term
    return total


if __name__ == "__main__":
    f: List[Fraction] = [Fraction(2), Fraction(3)]
    g: List[Fraction] = [Fraction(5), Fraction(7)]
    print("level 3 of (q^-1+2+3q)(q^-1+5+7q):", level_coefficient([f, g], 3))   # 29
    print("via locality decomposition       :", level_coefficient_local([f, g], 3))

    # McKay-Thompson shape: vanishing constant terms
    F = [Fraction(0), Fraction(3), Fraction(4)]
    G = [Fraction(0), Fraction(7), Fraction(9)]
    print("half-locality evaluation, level 3:",
          level_coefficient_local([F, G], 3, vanishing_constant_terms=True))     # 13
